// 代码分割（路由懒加载）
const Home = lazy(() => import('./pages/Home'));
const About = lazy(() => import('./pages/About'));

// 预加载
// HTML中
<link rel="preload" href="/critical.css" as="style">
<link rel="preload" href="/main.js" as="script">
<link rel="prefetch" href="/about.js">
<link rel="preconnect" href="https://cdn.example.com">

// JS中动态预加载
const link = document.createElement('link');
link.rel = 'preload';
link.as = 'script';
link.href = '/next-page.js';
document.head.appendChild(link);

// 图片懒加载
<img loading="lazy" src="image.jpg" alt="..." width="800" height="600">

// Intersection Observer懒加载
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const img = entry.target;
      img.src = img.dataset.src;
      observer.unobserve(img);
    }
  });
});

document.querySelectorAll('img[data-src]').forEach(img => observer.observe(img));

// 虚拟列表（react-window）
import { VariableSizeList } from 'react-window';

function VirtualList({ items }) {
  return (
    <VariableSizeList
      height={600}
      itemCount={items.length}
      itemSize={index => items[index].height}
      width="100%"
    >
      {({ index, style }) => <div style={style}>{items[index].name}</div>}
    </VariableSizeList>
  );
}

// Web Worker
// worker.js
self.onmessage = (e) => {
  const result = heavyComputation(e.data);
  self.postMessage(result);
};

// 主线程
const worker = new Worker('/worker.js');
worker.postMessage(data);
worker.onmessage = (e) => console.log(e.data);

// 减少重排
// 不好：多次读写布局属性
el.style.width = '100px';
const height = el.offsetHeight; // 触发重排
el.style.height = height + 'px';

// 好：批量操作
el.style.cssText = 'width:100px;height:100px;';
// 或使用class切换
el.classList.add('resized');

// CLS优化：图片设置尺寸
<img src="photo.jpg" width="800" height="600" alt="...">
// 或使用aspect-ratio
<img src="photo.jpg" style="aspect-ratio: 4/3" alt="...">

